create extension if not exists pgcrypto;
do $$ begin create type public.chebsel_role as enum ('president','secretary','treasurer','visitor'); exception when duplicate_object then null; end $$;
create table if not exists public.organizations(id uuid primary key default gen_random_uuid(),name text not null,acronym text not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.user_profiles(auth_user_id uuid primary key references auth.users(id) on delete cascade,organization_id uuid not null references public.organizations(id) on delete cascade,role public.chebsel_role not null,display_name text not null,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.devices(id uuid primary key,auth_user_id uuid not null references auth.users(id) on delete cascade,device_name text,platform text,last_seen_at timestamptz,last_sync_at timestamptz,active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.members(id uuid primary key,organization_id uuid not null references public.organizations(id) on delete cascade,legacy_id text,member_no text,first_name text not null default '',last_name text not null default '',phone text,active boolean not null default true,joined_at date,inactive_at date,notes text,version bigint not null default 1,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz);
create unique index if not exists members_org_legacy_unique on public.members(organization_id,legacy_id) where legacy_id is not null;
create table if not exists public.calendar_events(id uuid primary key,organization_id uuid not null references public.organizations(id) on delete cascade,legacy_id text,title text not null,event_date date,start_time time,end_time time,location text,event_type text not null default 'custom',status text not null default 'scheduled',reason text,version bigint not null default 1,created_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz);
create table if not exists public.attendance_events(id uuid primary key,organization_id uuid not null references public.organizations(id) on delete cascade,title text,event_type text,event_date date not null,start_time time,is_performance boolean not null default false,version bigint not null default 1,created_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz);
create table if not exists public.attendance_records(id uuid primary key,organization_id uuid not null references public.organizations(id) on delete cascade,attendance_event_id uuid not null references public.attendance_events(id) on delete cascade,member_id uuid not null references public.members(id),status text not null,reason text,arrival_time time,fine_amount numeric(14,2) not null default 0,version bigint not null default 1,created_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,unique(attendance_event_id,member_id));
create table if not exists public.financial_entries(id uuid primary key,organization_id uuid not null references public.organizations(id) on delete cascade,member_id uuid not null references public.members(id),entry_type text not null,source_type text,source_id uuid,description text,due_amount numeric(14,2) not null default 0,entry_date date not null,month_reference text,status text not null default 'open',version bigint not null default 1,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz);
create table if not exists public.payments(id uuid primary key,organization_id uuid not null references public.organizations(id) on delete cascade,member_id uuid not null references public.members(id),receipt_number text,payment_date date not null,amount numeric(14,2) not null check(amount>0),payment_method text,reference text,status text not null default 'active',corrects_payment_id uuid references public.payments(id),created_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.payment_allocations(id uuid primary key,organization_id uuid not null references public.organizations(id) on delete cascade,payment_id uuid not null references public.payments(id) on delete cascade,financial_entry_id uuid not null references public.financial_entries(id),amount numeric(14,2) not null check(amount>0),created_at timestamptz not null default now());
create table if not exists public.monthly_obligations(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,member_id uuid not null references public.members(id),year int not null,month int not null check(month between 1 and 12),amount numeric(14,2) not null default 125,status text not null default 'open',generated_at timestamptz not null default now(),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(member_id,year,month));
create table if not exists public.monthly_closings(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,month_reference text not null,closed_by uuid references auth.users(id),closed_at timestamptz not null default now(),reopened_by uuid references auth.users(id),reopened_at timestamptz,notes text,unique(organization_id,month_reference));
create table if not exists public.audit_logs(id uuid primary key,organization_id uuid not null references public.organizations(id) on delete cascade,auth_user_id uuid references auth.users(id),device_id uuid,action text not null,entity_type text,entity_id uuid,before_data jsonb,after_data jsonb,occurred_at timestamptz not null default now(),synced_at timestamptz);
create or replace function public.current_org_id() returns uuid language sql stable security definer set search_path=public as $$ select organization_id from public.user_profiles where auth_user_id=(select auth.uid()) and active=true limit 1 $$;
create or replace function public.current_chebsel_role() returns public.chebsel_role language sql stable security definer set search_path=public as $$ select role from public.user_profiles where auth_user_id=(select auth.uid()) and active=true limit 1 $$;
revoke all on function public.current_org_id() from public; revoke all on function public.current_chebsel_role() from public; grant execute on function public.current_org_id() to authenticated; grant execute on function public.current_chebsel_role() to authenticated;
 alter table public.user_profiles enable row level security; alter table public.devices enable row level security; alter table public.members enable row level security; alter table public.calendar_events enable row level security; alter table public.attendance_events enable row level security; alter table public.attendance_records enable row level security; alter table public.financial_entries enable row level security; alter table public.payments enable row level security; alter table public.payment_allocations enable row level security; alter table public.monthly_obligations enable row level security; alter table public.monthly_closings enable row level security; alter table public.audit_logs enable row level security;
grant usage on schema public to authenticated; grant select on public.user_profiles to authenticated; grant select,insert,update on public.devices,public.members,public.calendar_events,public.attendance_events,public.attendance_records,public.financial_entries,public.payments,public.payment_allocations,public.monthly_obligations,public.monthly_closings to authenticated; grant select,insert on public.audit_logs to authenticated;
create policy "profile self select" on public.user_profiles for select to authenticated using ((select auth.uid())=auth_user_id);
create policy "device own select" on public.devices for select to authenticated using ((select auth.uid())=auth_user_id); create policy "device own insert" on public.devices for insert to authenticated with check ((select auth.uid())=auth_user_id); create policy "device own update" on public.devices for update to authenticated using ((select auth.uid())=auth_user_id) with check ((select auth.uid())=auth_user_id);
create policy "members org select" on public.members for select to authenticated using (organization_id=(select public.current_org_id())); create policy "members staff insert" on public.members for insert to authenticated with check (organization_id=(select public.current_org_id()) and (select public.current_chebsel_role()) in ('president','secretary')); create policy "members staff update" on public.members for update to authenticated using (organization_id=(select public.current_org_id()) and (select public.current_chebsel_role()) in ('president','secretary')) with check (organization_id=(select public.current_org_id()));
create policy "calendar org select" on public.calendar_events for select to authenticated using (organization_id=(select public.current_org_id())); create policy "calendar staff insert" on public.calendar_events for insert to authenticated with check (organization_id=(select public.current_org_id()) and (select public.current_chebsel_role()) in ('president','secretary')); create policy "calendar staff update" on public.calendar_events for update to authenticated using (organization_id=(select public.current_org_id()) and (select public.current_chebsel_role()) in ('president','secretary')) with check (organization_id=(select public.current_org_id()));
insert into public.organizations(name,acronym) select 'Chœur d’Homme de l’Église Baptiste Sel et Lumière','CHEBSEL' where not exists(select 1 from public.organizations where acronym='CHEBSEL');
